INSERT INTO criaturas (id, nome, hp, ce, ca, mov, class_tipagem, class_tamanho, class_temperamento, eco_atividade, eco_reproducao, eco_expectativa_vida, eco_organizacao_tipo, eco_organizacao_quantidade, imagem_principal) VALUES
    (1, 'Alanzelha', 8, NULL, 10, 6, 'Terrestre', 'Médio', 'Neutro', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/alanzelha/alanzelha.png'),  -- alanzelha
    (2, 'Paquintos', 15, NULL, 13, 17, 'Terrestre', 'Grande', 'Neutro', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/paquintos/paquintos.png'),  -- paquintos
    (3, 'Reclama-Reclama', 1, NULL, 2, 10, 'Voador', 'Pequeno', 'Pacífico', 'Diurna', 'Desconhecida', NULL, 'Indivíduos Solitários', '1', 'assets/criaturas/reclama-reclama/reclama-reclama.png'),  -- reclama-reclama
    (4, 'Porco da Viela', 18, NULL, 8, 7, 'Terrestre', 'Grande', 'Pacífico', 'Diurna', 'Desconhecida', '50 anos', 'Rebanho', '2 a 12 indivíduos', 'assets/criaturas/porco_da_viela/porco_da_viela.png'),  -- porco_da_viela
    (5, 'Betassauro', 12, NULL, 12, 10, 'Terrestre', 'Médio', 'Pacífico', 'Diurna', 'Desconhecida', NULL, 'Doméstico', '1 a 4 indivíduos', 'assets/criaturas/betassauro/betassauro.png'),  -- betassauro
    (6, 'Levedor', 35, NULL, 8, 8, 'Terrestre', 'Grande', 'Pacífico', 'Noturna', 'Sexuada e vivípara. Durante as Pirilampadas, as fêmeas selecionam seus parceiros por meio de suas performances luminosas. Após a gestação, dão à luz poucos filhotes, que permanecem próximos da mãe e do rebanho durante os primeiros anos de vida.', '30 a 45 anos', 'Rebanho', '10 a 30 indivíduos', 'assets/criaturas/levedor/levedor.png'),  -- levedor
    (7, 'Dronalo', 6, NULL, 15, 13, 'Voador', 'Médio', 'Hostil', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/dronalo/dronalo.png'),  -- dronalo
    (8, 'Himoor', 10, NULL, 13, 15, 'Terrestre', 'Médio', 'Hostil', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/himoor/himoor.png'),  -- himoor
    (9, 'Beija-bundas', 3, NULL, 10, 15, 'Voador', 'Pequeno', 'Pacífico', 'Variável', 'Parasitária. Os Beija-Bundas depositam suas estruturas reprodutivas no interior de um hospedeiro, onde os ovos permanecem protegidos e utilizam reservas nutritivas até completarem seu desenvolvimento. Quando maduros, são expelidos junto às fezes do hospedeiro.', NULL, 'Bando', '2 a 10 indivíduos', 'assets/criaturas/beija-bundas/beija-bundas.png'),  -- beija-bundas
    (10, 'Barão-das-Nozes', 7, NULL, 13, 15, 'Voador', 'Médio', 'Neutro', 'Noturna', 'Baixa taxa de reprodução.', NULL, 'Solitário ou casal', '1 a 2 indivíduos', 'assets/criaturas/barao-das-nozes/barao-das-nozes.png'),  -- barao-das-nozes
    (11, 'Beijoqueira', 1, NULL, 2, 10, 'Voador', 'Pequeno', 'Pacífico', 'Variável', 'Desconhecida', NULL, 'Variável', 'Variável', 'assets/criaturas/beijoqueira/beijoqueira.png'),  -- beijoqueira
    (12, 'Bertoldi', 5, NULL, 12, 12, 'Voador', 'Pequeno', 'Hostil', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/bertoldi/bertoldi.png'),  -- bertoldi
    (13, 'Bufalote', 100, NULL, 10, 15, 'Terrestre', 'Gigante', 'Hostil', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/bufalote/bufalote.png'),  -- bufalote
    (14, 'Cacique', 2, NULL, 2, 8, 'Voador', 'Pequeno', 'Pacífico', 'Diurna', 'Durante as chuvas, os machos liberam seus gametas nas poças de lama onde as fêmeas permanecem parcialmente submersas, permitindo a fecundação dos ovos.', NULL, 'Grupo', 'Vários indivíduos, sempre liderados por um Cacique Tupã', 'assets/criaturas/cacique/cacique.png'),  -- cacique
    (15, 'Cavaleira', 15, NULL, 13, 12, 'Terrestre', 'Grande', 'Neutro', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/cavaleira/cavaleira.png'),  -- cavaleira
    (16, 'Fecalis', 14, NULL, 2, 5, 'Terrestre', 'Grande', 'Pacífico', 'Variável', 'Desconhecida', NULL, 'Rebanho', 'Numerosos', 'assets/criaturas/fecalis/fecalis.png'),  -- fecalis
    (17, 'Fizzgigs', 6, NULL, 8, 8, 'Terrestre', 'Pequeno', 'Neutro', 'Variável', 'Sexuada; os Fizzgigs são estritamente monogâmicos e mantêm o mesmo parceiro por toda a vida.', NULL, 'Casal', '2 indivíduos', 'assets/criaturas/fizzgigs/fizzgigs.png'),  -- fizzgigs
    (18, 'Hortênsio', 30, NULL, 12, 12, 'Terrestre', 'Grande', 'Neutro', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/hortensio/hortensio.png'),  -- hortensio
    (19, 'Jorrenilotre', 13, NULL, 3, 10, 'Terrestre', 'Grande', 'Pacífico', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/jorrenilotre/jorrenilotre.png'),  -- jorrenilotre
    (20, 'Los Pés', 25, NULL, 12, 10, 'Terrestre', 'Grande', 'Hostil', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/los_pes/los_pes.png'),  -- los_pes
    (21, 'Maninque', 80, NULL, 10, 13, 'Terrestre', 'Gigante', 'Neutro', 'Diurna', 'Vivípara e com cuidado parental extenso. As fêmeas dão à luz poucos filhotes por vez e permanecem com eles durante boa parte do crescimento.', '40 a 60 anos', 'Solitários ou pequenos grupos familiares, geralmente formados por uma fêmea e seus filhotes. Machos adultos costumam vagar sozinhos.', '1 a 4 indivíduos', 'assets/criaturas/maninques/maninques.png'),  -- maninque
    (22, 'Mooshritos', 6, NULL, 3, 10, 'Terrestre', 'Pequeno', 'Pacífico', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/mooshritos/mooshritos.png'),  -- mooshritos
    (23, 'Mumijal', 35, NULL, 13, 13, 'Terrestre', 'Grande', 'Hostil', 'Diurna', 'Sexuada; machos e fêmeas vivem separados e se encontram apenas durante os períodos reprodutivos.', NULL, 'Grupos separados por sexo', 'Variável', 'assets/criaturas/mumijal/mumijal.png'),  -- mumijal
    (24, 'Nininho', 6, NULL, 8, 10, 'Terrestre', 'Médio', 'Neutro', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/nininho/nininho.png'),  -- nininho
    (25, 'Nosfernando', 1, NULL, 10, 13, 'Terrestre', 'Pequeno', 'Hostil', 'Variável', 'Constroem ninhos em locais pequenos, escuros e protegidos, sendo especialmente comuns dentro de calçados.', NULL, 'Infestação', 'Variável', 'assets/criaturas/nosfernando/nosfernando.png'),  -- nosfernando
    (26, 'Nosquito', 1, NULL, 10, 15, 'Voador', 'Pequeno', 'Hostil', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/nosquito/nosquito.png'),  -- nosquito
    (27, 'Pentis', 6, NULL, 10, 14, 'Terrestre', 'Pequeno', 'Hostil', 'Variável', 'Não se reproduz neste estágio de desenvolvimento.', NULL, 'Ninhada', 'Vários indivíduos, geralmente acompanhados por Pentorrões adultos', 'assets/criaturas/pentis/pentis.png'),  -- pentis
    (28, 'Pentorrão', 12, NULL, 12, 12, 'Terrestre', 'Médio', 'Hostil', 'Variável', 'Reproduzem-se em ninhos construídos em locais reclusos, onde os indivíduos do bando se amontoam e permanecem por longos períodos.', NULL, 'Bando', '3 a 8 indivíduos', 'assets/criaturas/pentorrao/pentorrao.png'),  -- pentorrao
    (29, 'Pinteca', 15, NULL, 6, 8, 'Terrestre', 'Médio', 'Pacífico', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/pinteca/pinteca.png'),  -- pinteca
    (30, 'Rapieura', 40, NULL, 16, 17, 'Terrestre', 'Gigante', 'Hostil', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/rapieura/rapieura.png'),  -- rapieura
    (31, 'Variptor Mandicuris', 120, NULL, 16, 20, 'Voador', 'Gigante', 'Hostil', 'Diurna', 'Desconhecida', NULL, 'Colônia', '6 a 20 indivíduos', 'assets/criaturas/variptor_mandicuris/variptor_mandicuris.png'),  -- variptor_mandicuris
    (32, 'Falso-Levedor', 45, NULL, 11, 12, 'Terrestre', 'Grande', 'Hostil', 'Noturna', 'Ovípara. As fêmeas depositam poucos ovos em covas rasas escondidas entre os líquens e os vigiam até a eclosão. Os filhotes nascem com aparência semelhante à de filhotes de Levedor e permanecem escondidos nas proximidades de rebanhos durante os primeiros anos.', '15 a 25 anos', 'Solitário e territorialista. Raramente tolera outro adulto por perto, exceto durante a reprodução.', '1 indivíduo', 'assets/criaturas/falso-levedor/falso-levedor.png'),  -- falso-levedor
    (33, 'Nohta', 2, NULL, 14, 12, 'Aquático', 'Pequeno', 'Hostil', 'Noturna', 'Desconhecida', NULL, 'Solitário', '1 a 3 indivíduos', 'assets/criaturas/nohta/nohta.png'),  -- nohta
    (34, 'Corneteiro', 70, NULL, 9, 11, 'Terrestre', 'Gigante', 'Neutro', 'Diurna', 'Desconhecida', '30 a 45 anos', 'Manada', '10 a 20 indivíduos', 'assets/criaturas/corneteiro/corneteiro.png'),  -- corneteiro
    (35, 'Narigudo', 5, NULL, 14, 13, 'Aquático', 'Médio', 'Neutro', 'Diurna', 'Desconhecida', '5 a 8 anos', 'Cardume', '10 a 20 indivíduos', 'assets/criaturas/narigudo/narigudo.png'),  -- narigudo
    (36, 'Onça-do-lago', 10, NULL, 16, 14, 'Aquático', 'Médio', 'Hostil', 'Noturna', 'Desconhecida', '10 a 13 anos', 'Solitário', '1 indivíduo', 'assets/criaturas/onca-do-lago/onca-do-lago.png'),  -- onca-do-lago
    (37, 'Argenriço', 8, NULL, 10, 14, 'Aquático', 'Pequeno', 'Pacífico', 'Diurna', 'Desconhecida', '2 a 7 anos', 'Grupos Grandes', '40 a 60 indivíduos', 'assets/criaturas/argenrico/argenrico.png'),  -- argenrico
    (38, 'Buleque', 13, NULL, 13, 15, 'Aquático', 'Grande', 'Neutro', 'Diurna', 'Desconhecida', '2 a 7 anos', 'Grupos Grandes', '40 a 60 indivíduos', 'assets/criaturas/buleque/buleque.png'),  -- buleque
    (39, 'Mozilugue', 8, NULL, 10, 14, 'Terrestre', 'Grande', 'Hostil', 'Diurna', 'Desconhecida', '2 a 7 anos', 'Grupos Grandes', '40 a 60 indivíduos', 'assets/criaturas/mozilugue/mozilugue.png'),  -- mozilugue
    (40, 'Tenor', 8, NULL, 10, 14, 'Terrestre', 'Médio', 'Pacífico', 'Diurna', 'Desconhecida', '2 a 7 anos', 'Grupos Grandes', '40 a 60 indivíduos', 'assets/criaturas/tenor/tenor.png'),  -- tenor
    (41, 'Prima Dona', 30, NULL, 10, 14, 'Terrestre', 'Grande', 'Pacífico', 'Diurna', 'Desconhecida', '2 a 7 anos', 'Grupos Grandes', '40 a 60 indivíduos', 'assets/criaturas/prima-dona/prima-dona.png');  -- prima-dona
