INSERT INTO criatura_habilidades (criatura_id, nome, tipo, descricao) VALUES
    (1, 'Fazer Caldo', NULL, 'Produz o característico caldo das Alanzelhas nas Alandocas.'),
    (1, 'Defesa Coletiva', NULL, 'Quando uma Alanzelha é atacada, indivíduos próximos podem se juntar ao combate.'),
    (2, 'Farejador de Trufas', NULL, 'Fareja trufas e outros alimentos subterrâneos com grande precisão.'),
    (3, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (4, 'Corpo Pesado', NULL, 'O Porco da Viela possui vantagem em testes para resistir a efeitos que tentem empurrá-lo ou derrubá-lo.'),
    (4, 'Maminha', NULL, 'Um Porco da Viela muito assustado pode tentar chicotear sua maminha em direção ao alvo, causando 1d4 de dano.'),
    (5, 'Proteger o Mestre', NULL, 'O Betassauro fica agressivo quando seu dono está em perigo. Enquanto estiver defendendo seu mestre, ele ignora seu comportamento normalmente dócil e tentará atacar ou afastar a ameaça.'),
    (5, 'Investida Poderosa', NULL, 'O Betassauro dispara em linha reta contra um alvo usando a força de suas pernas e o peso do corpo. A investida causa forte impacto e pode derrubar ou empurrar o alvo.'),
    (5, 'Dentada', NULL, 'Os Dentes dos Betassauros são bem proeminentes, uma mordida pode ser dolorida, causando 1d6 de dano.'),
    (6, 'Pólipos Luminescentes', 'Ativa', 'Após se alimentar de líquens luminescentes, o Levedor favorece o crescimento de bactérias fotossintetizantes que formam pólipos em suas costas. Quanto mais o animal se alimenta, mais intensamente esses pólipos brilham.'),
    (7, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (8, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (9, 'Bico Coprófago', 'Passiva', 'O Beija-Bundas possui um bico altamente adaptado para alcançar e consumir resíduos fecais diretamente do corpo de outros animais, demonstrando preferência por fezes ainda aquecidas.'),
    (9, 'Postura Parasitária', 'Ação', 'O Beija-Bundas pode tentar utilizar uma criatura como hospedeira para seus ovos. Durante o processo, deixa no interior do hospedeiro seu aparato reprodutivo, que fornece proteção e nutrientes aos ovos até que estejam maduros.'),
    (10, 'Golpe nos Olhos', 'Ação', 'Quando ameaçado, o Barão-das-Nozes pode atacar os olhos de seu agressor com suas garras afiadas, buscando cegá-lo ou desorientá-lo para fugir em segurança.'),
    (11, 'Beijoca', 'Ação', 'A Beijoqueira faz biquinho e beija uma criatura para beber seu suor. O beijo é quente e úmido, provocando uma sensação agradável e liberando uma pequena dose de dopamina. Beijocas recebidas em excesso podem provocar um inchaço temporário nos lábios do alvo.'),
    (11, 'Lábios Sensíveis', 'Passiva', 'Os lábios extremamente sensíveis da Beijoqueira conseguem perceber alterações incomuns no organismo de uma criatura. Por isso, esses animais podem ser utilizados para identificar o uso de Charrébolona e determinadas alterações mágicas.'),
    (12, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (13, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (14, 'Dança da Tempestade', 'Passiva', 'Quando uma chuva ou tempestade está prestes a ocorrer, um grupo de Caciques inicia uma dança característica. Observar corretamente essa dança permite prever mudanças no clima antes que elas aconteçam.'),
    (14, 'Maracas Naturais', 'Passiva', 'Durante suas danças, os exoesqueletos dos Caciques chocam-se uns contra os outros, produzindo sons semelhantes aos de maracás.'),
    (15, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (17, 'Mordida', 'Ação', 'Apesar do pequeno porte, o Fizzgig possui uma amplitude de mordida impressionante e pode causar ferimentos consideráveis com suas mandíbulas.'),
    (17, 'Rolamento', 'Movimento', 'Embora possua duas patas, o Fizzgig normalmente se locomove enrolando o corpo e rolando pelo chão.'),
    (18, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (19, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (20, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (21, 'Olhos Pedunculados', 'Passiva', 'Além de enxergar enquanto se alimentam, cada olho se move de forma independente. +4 em testes de percepção.'),
    (21, 'Brado Maninque', 'Passiva', 'Os Maninques se comunicam com brados graves que podem ser ouvidos a longas distâncias. Se filhotes estiverem em perigo, Maninques mães podem tentar chamar outros Maninques na região para ajudá-las.'),
    (21, 'Pisoteio', 'Ativa', 'Maninques, por serem animais gigantes, caso se sintam ameaçados, pisoteiam seus algozes, podendo causar até 1d10+10 de dano.'),
    (22, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (23, 'Fúria do Macho', 'Passiva', 'Mumijais machos são extremamente agressivos e possuem pouca capacidade de avaliar ameaças ou consequências, atacando com facilidade outros indivíduos de sua espécie e criaturas próximas.'),
    (24, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (25, 'Síndrome do Valquíria', 'Passiva', 'O Nosfernando pode transmitir uma praga que afeta o encéfalo de determinados indivíduos, causando alterações comportamentais associadas à chamada Síndrome do Valquíria. Mulheres e indivíduos naturalmente afeminados não são afetados.'),
    (25, 'Atração por Testosterona', 'Passiva', 'Nosfernandos são especialmente atraídos por indivíduos com altos níveis de testosterona, podendo persegui-los ou se concentrar em locais frequentados por eles.'),
    (25, 'Garras Afiadas', 'Ação', 'O Nosfernando possui pequenas garras extremamente afiadas, capazes de provocar cortes rápidos apesar do reduzido tamanho do animal.'),
    (26, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (27, 'Corpo Juvenil', 'Passiva', 'O Pentis ainda não desenvolveu os braços característicos dos Pentorrões adultos. Seus membros anteriores surgem apenas em estágios posteriores de crescimento.'),
    (28, 'Ataque em Bando', 'Passiva', 'Pentorrões tornam-se mais perigosos quando atacam em grupo, cercando suas vítimas e avançando de diferentes direções.'),
    (28, 'Colecionador de Brilhos', 'Passiva', 'Pentorrões são fortemente atraídos por objetos brilhantes e tendem a roubá-los e levá-los para seus ninhos.'),
    (29, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (30, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (31, 'Reclamar', NULL, 'Reclamas-reclamas reclamam de tudo, desde o clima até a comida. Elas podem ser irritantes, mas não são agressivas.'),
    (32, 'Mimetismo de Levedor', 'Passiva', 'Com o corpo rente ao chão e as bocas fechadas, o Falso-Levedor é praticamente indistinguível de um Levedor à distância. +6 em testes para se passar por um Levedor.'),
    (32, 'Três Bocas', 'Ativa', 'As três bocas se movem de forma independente, permitindo morder alvos diferentes ou concentrar todos os ataques em um só. Cada boca dá 1d12 de dano.'),
    (32, 'Olhos Agrupados', 'Passiva', 'Os dois aglomerados de olhos enxergam bem no escuro e cobrem um campo de visão muito amplo. +4 em testes de percepção durante a noite.'),
    (33, 'Pedra-Viva', 'Passiva', 'O corpo do Nohta é coberto por depósitos minerais cristalizados. Essas formações aumentam de tamanho lentamente ao longo de sua vida e fazem com que o animal se pareça com uma pequena pedra cristalina quando permanece imóvel.'),
    (33, 'Pesadelo d''Água', 'Ativa', 'Quando percebe um animal parcialmente submerso, o Nohta pode tentar penetrar pela uretra e alojar-se no trato urinário. Uma vez instalado, seus cristais dificultam sua expulsão e provocam dores intensas no hospedeiro.'),
    (34, 'Cornetada', 'Ativa', 'Quando ameaçado, o Corneteiro infla completamente o papo e libera um som ensurdecedor através de todas as suas cornetas. Criaturas próximas podem ficar temporariamente desorientadas pelo som. Teste de Resistência 18.'),
    (35, 'Cornetas', 'Passiva', 'Ao redor da cabeça do Corneteiro crescem grandes estruturas ocas semelhantes a cornetas. O animal consegue direcionar o ar de seus pulmões através delas, produzindo chamados de diferentes tons que podem ser ouvidos a grandes distâncias'),
    (35, 'Cornetada', 'Ativa', 'Quando ameaçado, o Corneteiro infla completamente o papo e libera um brado ensurdecedor através de todas as suas cornetas. Criaturas próximas podem ficar temporariamente desorientadas pelo som.'),
    (36, 'Cornetas', 'Passiva', 'Ao redor da cabeça do Corneteiro crescem grandes estruturas ocas semelhantes a cornetas. O animal consegue direcionar o ar de seus pulmões através delas, produzindo chamados de diferentes tons que podem ser ouvidos a grandes distâncias'),
    (36, 'Cornetada', 'Ativa', 'Quando ameaçado, o Corneteiro infla completamente o papo e libera um brado ensurdecedor através de todas as suas cornetas. Criaturas próximas podem ficar temporariamente desorientadas pelo som.'),
    (37, 'Cornetas', 'Passiva', 'Ao redor da cabeça do Corneteiro crescem grandes estruturas ocas semelhantes a cornetas. O animal consegue direcionar o ar de seus pulmões através delas, produzindo chamados de diferentes tons que podem ser ouvidos a grandes distâncias'),
